// Общие шаги для тестов даты/времени сообщений поддержки (#3db49a08, план specs/support.md). Только чтение:
// не отвечать, не нажимать «Close Chat». Сессия admin — ADMIN_STATE из addresses/address-helpers.ts.
import { expect, Browser, BrowserContextOptions, Page, TestInfo } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from '../addresses/address-helpers';

export { ADMIN_STATE, setEnglish };

/** QA-обращение Chat на проде (компания test, автор — admin «Kirill»), ≥ 5 сообщений. Закроют/удалят — заменить здесь. */
export const TICKET_ID = '8c3d2ad8-bb86-41f2-8340-3c614070724f';
export const TICKET_TITLE = 'Chat — QA-support 14.10';
export const TICKET_URL = `/SupportTicketDetail?id=${TICKET_ID}`;
export const MIN_MESSAGES = 5;

/** Формат метки из тикета: DD/MM/YY HH:mm. */
export const STAMP = /^\d{2}\/\d{2}\/\d{2} \d{2}:\d{2}$/;
const STAMP_SRC = '\\d{2}/\\d{2}/\\d{2} \\d{2}:\\d{2}';
/** Шапка экрана обращения: «Chat · DD/MM/YY HH:mm» (HE — «צ׳אט · …»). */
export const DETAIL_HEADER_EN = new RegExp(`^Chat · ${STAMP_SRC}$`);
export const DETAIL_HEADER_HE = new RegExp(`^צ[׳']אט · ${STAMP_SRC}$`);
/** Шапка переписки в Support Console: «Chat · Customer: Kirill · DD/MM/YY HH:mm». */
export const INBOX_HEADER_EN = new RegExp(`^Chat · Customer: .+ · ${STAMP_SRC}$`);
export const INBOX_HEADER_HE = new RegExp(`^צ[׳']אט · .+ · ${STAMP_SRC}$`);

export const CHAT_TAB_EN = /^Chat\s*\d*$/;
export const CHAT_TAB_HE = /^צ[׳']אט\s*\d*$/;

/** Метки даты/времени: первая — шапка обращения, остальные — сообщения. */
export const stamps = (page: Page) => page.locator('time[dir="ltr"]');

/** Экран обращения: дождаться шапки и всех сообщений. */
export async function openTicketDetail(page: Page, header: RegExp = DETAIL_HEADER_EN) {
  await page.goto(TICKET_URL);
  await expect(page.getByText(header)).toBeVisible();
  await expect(stamps(page).nth(MIN_MESSAGES)).toBeVisible(); // шапка + ≥ 5 сообщений
}

/** Support Console: вкладка «Chat» → QA-обращение (на десктопе оно и в History — берём видимое). */
export async function openInboxChat(page: Page, chatTab: RegExp = CHAT_TAB_EN, header: RegExp = INBOX_HEADER_EN) {
  await page.goto('/supportinbox');
  await page.getByRole('button', { name: chatTab }).first().click();
  await page.getByRole('button').filter({ hasText: TICKET_TITLE }).filter({ visible: true }).first().click();
  await expect(page.getByText(header)).toBeVisible();
  await expect(stamps(page).nth(MIN_MESSAGES)).toBeVisible();
}

/** Каждая метка на экране — DD/MM/YY HH:mm. Возвращает { datetime → текст }. */
export async function expectAllStamps(page: Page): Promise<Record<string, string>> {
  const all = await stamps(page).evaluateAll((els) =>
    els.map((e) => ({ dt: e.getAttribute('datetime') || '', text: (e.textContent || '').trim() })),
  );
  expect(all.length).toBeGreaterThanOrEqual(MIN_MESSAGES + 1);
  const map: Record<string, string> = {};
  for (const s of all) {
    expect(s.text, `метка ${s.dt}`).toMatch(STAMP);
    map[s.dt] = s.text;
  }
  return map;
}

/** Ожидаемая метка: ISO-время в заданном часовом поясе, DD/MM/YY HH:mm. */
export function formatStamp(iso: string, timeZone: string): string {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone, day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(new Date(iso));
  const g = (t: string) => parts.find((p) => p.type === t)!.value;
  return `${g('day')}/${g('month')}/${g('year')} ${g('hour')}:${g('minute')}`;
}

/** Метка DD/MM/YY HH:mm → минуты (для разницы между поясами). */
export function stampMinutes(stamp: string): number {
  const [, d, m, y, h, mi] = stamp.match(/^(\d{2})\/(\d{2})\/(\d{2}) (\d{2}):(\d{2})$/)!.map(Number);
  return Date.UTC(2000 + y, m - 1, d, h, mi) / 60_000;
}

/** Окно admin с заданным часовым поясом (параметры устройства — из текущего проекта). */
export async function adminPageIn(browser: Browser, testInfo: TestInfo, timezoneId: string): Promise<Page> {
  const use = testInfo.project.use as BrowserContextOptions;
  const context = await browser.newContext({
    baseURL: use.baseURL, locale: use.locale, viewport: use.viewport, userAgent: use.userAgent,
    deviceScaleFactor: use.deviceScaleFactor, isMobile: use.isMobile, hasTouch: use.hasTouch,
    storageState: ADMIN_STATE, timezoneId,
  });
  const page = await context.newPage();
  await setEnglish(page);
  return page;
}

/** Все метки целиком внутри ширины экрана, горизонтальной прокрутки нет. */
export async function expectStampsInViewport(page: Page) {
  const { boxes, vw, sw } = await page.evaluate(() => ({
    boxes: [...document.querySelectorAll('time[dir="ltr"]')].map((e) => {
      const r = e.getBoundingClientRect();
      return { text: (e.textContent || '').trim(), left: r.left, right: r.right };
    }),
    vw: window.innerWidth,
    sw: document.documentElement.scrollWidth,
  }));
  expect(boxes.length).toBeGreaterThanOrEqual(MIN_MESSAGES + 1);
  for (const b of boxes) {
    expect(b.text).toMatch(STAMP);
    expect(b.left, `${b.text}: левый край`).toBeGreaterThanOrEqual(0);
    expect(b.right, `${b.text}: правый край`).toBeLessThanOrEqual(vw);
  }
  expect(sw, 'горизонтальная прокрутка').toBeLessThanOrEqual(vw);
}
